const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',folder:'M3 7V5h6l2 3h10v12H3z',check:'M9 11l3 3L22 4 M21 12v8H3V3h13',book:'M12 5v16 M3 3c4-1 6 0 9 2 3-2 5-3 9-2v16c-4-1-6 0-9 2-3-2-5-3-9-2z',type:'M4 4h16 M12 4v16 M8 20h8',layers:'M12 3L2 8l10 5 10-5z M2 12l10 5 10-5 M2 16l10 5 10-5',bookmark:'M6 3h12v18l-6-4-6 4z',search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',arrow:'M5 12h14 M13 6l6 6-6 6',code:'M8 6l-6 6 6 6 M16 6l6 6-6 6 M14 3l-4 18',download:'M12 3v12 M7 10l5 5 5-5 M3 16v5h18v-5'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.book}"/></svg>`;
document.querySelectorAll('[data-icon]').forEach(e=>e.innerHTML=icon(e.dataset.icon));
let state={brief:{},checks:{},saved:[],theme:'light'},data,currentDoc,search='',filter='',letter='';
try{state={...state,...JSON.parse(localStorage.getItem(window.PLATFORM_STORAGE_KEY)||'{}')};}catch{}
if(!Array.isArray(state.saved))state.saved=[];
state.brief=state.brief&&typeof state.brief==='object'?state.brief:{};state.checks=state.checks&&typeof state.checks==='object'?state.checks:{};
function persist(){try{localStorage.setItem(window.PLATFORM_STORAGE_KEY,JSON.stringify(state));return true;}catch{toast('Browser storage is unavailable. Export your work to keep a copy.');return false;}}
function toast(msg){$('#toast').textContent=msg;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',3200);}
function applyTheme(){document.body.classList.toggle('dark',state.theme==='dark');}applyTheme();
$('#theme').onclick=()=>{state.theme=state.theme==='dark'?'light':'dark';applyTheme();persist();};
const checklist=[['Before you build',['Describe the user, problem, and success criteria','Choose a small, testable first milestone','Create a feature branch','Review project context and agent instructions']],['During the session',['Ask the agent for a plan and review it','Implement one small change at a time','Run the relevant checks and inspect the result','Review the diff before committing']],['Ready to hand off',['Check empty, error, and mobile states','Check keyboard navigation and labels','Keep secrets out of source control','Record what changed and the next task']]];
function progress(){const values=checklist.flatMap((g,gi)=>g[1].map((_,i)=>!!state.checks[`${gi}-${i}`]));return {done:values.filter(Boolean).length,total:values.length};}
function checkRows(limit){let count=0;return checklist.map((g,gi)=>{const rows=g[1].map((t,i)=>{if(limit&&count++>=limit)return '';return `<label class="check-row"><input type="checkbox" data-check="${gi}-${i}" ${state.checks[`${gi}-${i}`]?'checked':''}><span>${esc(t)}</span></label>`;}).join('');return limit?rows:`<div class="session-group"><h3>0${gi+1} / ${g[0]}</h3>${rows}</div>`;}).join('');}
function bindChecks(){document.querySelectorAll('[data-check]').forEach(e=>e.onchange=()=>{state.checks[e.dataset.check]=e.checked;persist();updateProgress();});}
function updateProgress(){let p=progress();document.querySelectorAll('[data-progress-text]').forEach(e=>e.textContent=`${p.done} of ${p.total} completed`);document.querySelectorAll('[data-progress-bar]').forEach(e=>e.style.width=`${p.done/p.total*100}%`);}
function shell(title,sub,action=''){return `<div class="breadcrumb">Workspace <span>/</span> ${esc(title)}</div><div class="page-top"><div><h1>${esc(title)}</h1><p class="subtle">${esc(sub)}</p></div>${action}</div>`;}
function excerpt(d){return d.body.replace(/!\[[^\]]*\]\([^)]*\)/g,'').replace(/^#+.*$/gm,'').replace(/\[([^\]]+)\]\([^)]*\)/g,'$1').replace(/[#*`<>|_]/g,'').replace(/\s+/g,' ').trim().slice(0,155);}
function overview(){const count=s=>data.docs.filter(d=>d.source===s).length;$('#main').innerHTML=shell('Your ideas, with a plan.','A little structure for the things you want to build.',`<a class="button primary" href="#project">${icon('folder')} ${state.brief.name?'Open project':'Start a project'}</a>`)+`<section class="hero"><div class="hero-copy"><div class="eyebrow">FROM FIRST PROMPT TO FINISHED PROJECT</div><h2>Keep the vibe.<br>Build with intention.</h2><p>Turn a rough idea into a clear brief, give your agent the right context, and keep good engineering habits along the way.</p><div class="actions"><a class="button primary" href="#project">Create your project brief ${icon('arrow')}</a><a class="text-link" href="#library/vibe">Explore the playbook ↗</a></div></div><div class="hero-flow"><div class="flow-step"><span class="flow-number">01</span><div><strong>Make it clear</strong><small>Define the problem & the people</small></div></div><div class="flow-step"><span class="flow-number">02</span><div><strong>Build in small steps</strong><small>Plan, prompt, review, repeat</small></div></div><div class="flow-step"><span class="flow-number">03</span><div><strong>Ship with confidence</strong><small>Test the details that matter</small></div></div></div></section><div class="section-title"><h2>Your building blocks</h2><a class="text-link" href="#sources">Meet the sources ↗</a></div><div class="grid"><a class="collection" href="#library/vibe"><div class="collection-icon">${icon('code')}</div><h3>Vibe Coding Playbook</h3><p>Context files, better prompts, and a repeatable rhythm for working with AI.</p><footer><span>${count('vibe')} practical chapters</span>${icon('arrow')}</footer></a><a class="collection" href="#library/engineering"><div class="collection-icon">${icon('book')}</div><h3>Engineering fundamentals</h3><p>Microsoft's field guide to testing, code reviews, architecture, and delivery.</p><footer><span>${count('engineering')} engineering guides</span>${icon('arrow')}</footer></a><a class="collection" href="#glossary"><div class="collection-icon">${icon('type')}</div><h3>Speak the language of UX</h3><p>Make design conversations easier with a shared vocabulary.</p><footer><span>${data.terms.length} UX terms, explained</span>${icon('arrow')}</footer></a></div><div class="split"><section><div class="section-title"><h2>A good place to start</h2><a class="text-link" href="#library">Browse all ↗</a></div><div class="panel">${['02-context-files','07-prompt-engineering','04-workflow'].map((s,i)=>{const d=data.docs.find(d=>d.id.includes(s));return d?`<button class="row" data-doc="${esc(d.id)}"><span class="number">0${i+1}</span><div><strong>${esc(d.title)}</strong><small>Vibe Coding Playbook</small></div><span class="arrow">↗</span></button>`:'';}).join('')}</div></section><section><div class="section-title"><h2>Your session, on track</h2><a class="text-link" href="#session">Full checklist ↗</a></div><div class="panel"><div class="progress-meta"><span>SESSION CHECKLIST</span><span data-progress-text></span></div><div class="progress"><div data-progress-bar></div></div>${checkRows(3)}</div></section></div><div class="footer-note"><span>Good context makes better code.</span><span>Saved on this browser · Export anytime</span></div>`;bindDocs();bindChecks();updateProgress();}
function searchBar(placeholder,options=[]){return `<div class="toolbar"><label class="search">${icon('search')}<input id="search" aria-label="${esc(placeholder)}" placeholder="${esc(placeholder)}" value="${esc(search)}"></label>${options.length?`<select id="filter" aria-label="Filter by category"><option value="">All categories</option>${options.map(c=>`<option ${filter===c?'selected':''} value="${esc(c)}">${esc(c)}</option>`).join('')}</select>`:''}</div>`;}
function bindSearch(render){$('#search').oninput=e=>{search=e.target.value;render();};if($('#filter'))$('#filter').onchange=e=>{filter=e.target.value;render();};}
function matches(d){return (!search||`${d.title} ${d.body||''} ${d.category||''}`.toLowerCase().includes(search.toLowerCase()))&&(!filter||d.category===filter);}
function library(source,saved=false){const docs=data.docs.filter(d=>(!source||d.source===source)&&(!saved||state.saved.includes(d.id)));$('#main').innerHTML=shell(saved?'Saved reading':source==='vibe'?'Vibe Coding Playbook':source==='engineering'?'Engineering fundamentals':'The playbook library',saved?'Your bookmarked guides, ready when you need them.':'Search the full text. Read here, or open the original source.')+searchBar('Search guides, topics, and keywords',[...new Set(docs.map(d=>d.category))].sort())+'<div id="results"></div>';const render=()=>{const found=docs.filter(matches);$('#results').innerHTML=`<div class="results-meta">${found.length} guides${search?' matching “'+esc(search)+'”':''}</div>`+(found.map(d=>`<div class="doc-row"><span class="collection-icon" style="margin:0">${icon(d.source==='vibe'?'code':'book')}</span><button class="doc-open" data-doc="${esc(d.id)}"><h3>${esc(d.title)}</h3><p>${esc(excerpt(d))}…</p><div style="margin-top:7px"><span class="tag">${esc(d.collection)}</span> <span class="tag">${esc(d.category)}</span></div></button><button class="bookmark-btn ${state.saved.includes(d.id)?'saved':''}" data-save="${esc(d.id)}" aria-label="${state.saved.includes(d.id)?'Unsave':'Save'} ${esc(d.title)}">${icon('bookmark')}</button></div>`).join('')||`<div class="empty">${saved&&!docs.length?'Save an article from the library to find it here.':'No matching guides. Try another search or category.'}</div>`);bindDocs();document.querySelectorAll('[data-save]').forEach(e=>e.onclick=()=>{toggleSave(e.dataset.save);if(saved)library(source,saved);else render();});};bindSearch(render);render();}
function safeUrl(url,base){try{const u=new URL(url,base);return ['https:','http:'].includes(u.protocol)?u.href:'#';}catch{return '#';}}
function inline(text,base){return esc(text).replace(/`([^`]+)`/g,'<code>$1</code>').replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/\[([^\]]+)\]\(([^)]+)\)/g,(_,label,url)=>`<a target="_blank" rel="noopener noreferrer" href="${esc(safeUrl(url.replace(/&amp;/g,'&'),base))}">${label}</a>`);}
function markdown(text,base){let code=false,buf=[],html=[],list=false;for(const line of text.split('\n')){if(/^```/.test(line)){if(code){html.push('<pre><code>'+esc(buf.join('\n'))+'</code></pre>');buf=[];}code=!code;continue;}if(code){buf.push(line);continue;}if(/^!\[/.test(line.trim()))continue;let h=line.match(/^(#{1,6})\s+(.+)$/);if(h){if(list){html.push('</ul>');list=false;}html.push(`<h${h[1].length}>${inline(h[2],base)}</h${h[1].length}>`);}else if(/^\s*[-*]\s+/.test(line)){if(!list){html.push('<ul>');list=true;}html.push('<li>'+inline(line.replace(/^\s*[-*]\s+/,''),base)+'</li>');}else{if(list){html.push('</ul>');list=false;}if(line.trim())html.push(line.startsWith('|')?`<div class="md-table">${inline(line,base)}</div>`:'<p>'+inline(line,base)+'</p>');}}if(list)html.push('</ul>');if(code)html.push('<pre>'+esc(buf.join('\n'))+'</pre>');return html.join('');}
function bindDocs(){document.querySelectorAll('[data-doc]').forEach(e=>e.onclick=()=>openDoc(e.dataset.doc));}
function openDoc(id){currentDoc=data.docs.find(d=>d.id===id);if(!currentDoc)return;$('#reader-source').textContent=currentDoc.collection;$('#article').innerHTML=markdown(currentDoc.body,currentDoc.url)+`<div class="source subtle">${esc(currentDoc.collection)} · ${currentDoc.source==='vibe'?'MIT':'CC BY 4.0'} · Original text, presented in a simplified reader.<br><a href="${esc(currentDoc.url)}" target="_blank" rel="noopener noreferrer">Read the original article ↗</a></div>`;$('#save-doc').textContent=state.saved.includes(id)?'Unsave reading':'Save reading';$('#reader').showModal();$('#reader').scrollTop=0;}
function toggleSave(id){state.saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];persist();$('#saved-count').textContent=state.saved.length;}
$('#save-doc').onclick=()=>{if(!currentDoc)return;toggleSave(currentDoc.id);$('#save-doc').textContent=state.saved.includes(currentDoc.id)?'Unsave reading':'Save reading';};
$('#close-reader').onclick=()=>{$('#reader').close();if(location.hash==='#bookmarks')library('',true);};
function glossary(){const letters=[...new Set(data.terms.map(t=>t.title[0].toUpperCase()))].sort();$('#main').innerHTML=shell('The UX glossary','A shared language for building things people can use. Definitions by UX Mastery.')+searchBar('Find a UX term or definition')+`<div class="letters"><button data-letter="" class="${!letter?'active':''}">All</button>${letters.map(l=>`<button data-letter="${esc(l)}" class="${letter===l?'active':''}">${esc(l)}</button>`).join('')}</div><div id="results"></div><p class="note">Definitions reproduced from the Collaborative UX Glossary, CC BY-SA 4.0. <a class="text-link" href="#sources">Attribution & license ↗</a></p>`;const render=()=>{let terms=data.terms.filter(t=>(!letter||t.title[0].toUpperCase()===letter)&&matches(t));$('#results').innerHTML=`<div class="results-meta">${terms.length} terms</div>`+(terms.map(t=>`<div class="term"><h3>${esc(t.title)}</h3><p>${inline(t.body,'https://github.com/uxmastery/collaborative-ux-glossary/blob/master/glossary_en.md')}</p></div>`).join('')||'<div class="empty">No matching terms. Try a broader search.</div>');};document.querySelectorAll('[data-letter]').forEach(e=>e.onclick=()=>{letter=e.dataset.letter;document.querySelectorAll('[data-letter]').forEach(b=>b.classList.toggle('active',b.dataset.letter===letter));render();});bindSearch(render);render();}
function resources(){const options=[...new Set(data.resources.map(r=>r.category))];$('#main').innerHTML=shell('The design resource shelf','Tools, references, and inspiration collected by Michael P Wright. Links reflect the original collection.')+searchBar('Search tools and resources',options)+'<div id="results"></div><p class="note">External resources may change or require accounts. ✴️ marks an affiliate link in the original collection.</p>';const render=()=>{const found=data.resources.filter(matches);$('#results').innerHTML=`<div class="results-meta">${found.length} resources</div><div class="resource-grid">${found.map(r=>`<a class="resource" target="_blank" rel="noopener noreferrer" href="${esc(safeUrl(r.url))}"><span class="arrow">↗</span><h3>${esc(r.title)}</h3><small>${esc(r.category)} · ${esc(new URL(r.url).hostname)}</small></a>`).join('')}</div>`+(found.length?'':'<div class="empty">No matching resources.</div>');};bindSearch(render);render();}
const fields=[['name','Project name','e.g. A calmer task manager'],['audience','Who is it for?','e.g. Freelance designers'],['goal','What problem will it solve?','Describe the outcome you want users to achieve.','wide'],['features','First milestone','List the smallest useful set of features, one per line.','wide'],['stack','Stack & tools','e.g. React, TypeScript, Supabase'],['constraints','Constraints & non-goals','e.g. No payments in v1; keyboard accessible'],['verify','How will you verify it?','e.g. A user can create, edit, and complete a task on mobile.','wide']];
function prompt(){const b=state.brief;return `# ${b.name||'Untitled project'}\n\n## Goal\n${b.goal||'Define the problem to solve.'}\n\n## Audience\n${b.audience||'Define the intended users.'}\n\n## First milestone\n${b.features||'Define the smallest useful deliverable.'}\n\n## Stack\n${b.stack||'Choose an appropriate stack and explain the tradeoffs.'}\n\n## Constraints and non-goals\n${b.constraints||'Keep scope focused on the first milestone.'}\n\n## Verification\n${b.verify||'Test the main user flow and relevant error states.'}\n\n## Working approach\nRead the existing project context. Propose a short implementation plan and state assumptions. Build in small steps, review changes, and run the relevant checks. Report what changed, what passed, and any limitations.\n`;}
function download(name,text,type='text/markdown'){const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function project(){const b=state.brief;$('#main').innerHTML=shell('Start with a clear brief.','Turn the idea in your head into context your coding agent can work with.',`<a class="button primary" href="#build">Build this project →</a>`)+`<form id="brief-form" class="panel"><div class="form-grid">${fields.map(([id,label,placeholder,wide])=>`<div class="field ${wide||''}"><label for="brief-${id}">${label}</label>${wide?`<textarea id="brief-${id}" name="${id}" placeholder="${placeholder}" maxlength="12000">${esc(b[id]||'')}</textarea>`:`<input id="brief-${id}" name="${id}" placeholder="${placeholder}" value="${esc(b[id]||'')}" maxlength="2000">`}</div>`).join('')}</div><div class="form-footer actions"><button class="primary" type="submit">Generate agent prompt ${icon('arrow')}</button><span class="subtle" id="save-status">Changes save in this browser.</span></div></form><div class="section-title"><h2>Your agent handoff</h2><button id="copy-prompt">Copy prompt</button></div><div class="panel"><p class="subtle">Use this brief in your preferred coding agent. Open Build projects to create a project and run this brief with your coding agent.</p><pre class="prompt" id="prompt-preview"></pre><div class="file-buttons"><button data-export="PROJECT.md">${icon('download')} PROJECT.md</button><button data-export="AGENTS.md">AGENTS.md</button><button data-export="TASKS.md">TASKS.md</button><button id="backup">Export workspace backup</button><label class="button" style="cursor:pointer">Import backup<input id="import-backup" type="file" accept="application/json,.json" hidden></label></div></div>`;$('#prompt-preview').textContent=prompt();$('#brief-form').oninput=e=>{if(!e.target.name)return;state.brief[e.target.name]=e.target.value;const ok=persist();$('#save-status').textContent=ok?'Saved to this browser.':'Storage unavailable — export a backup.';$('#prompt-preview').textContent=prompt();};$('#brief-form').onsubmit=e=>{e.preventDefault();$('#prompt-preview').textContent=prompt();$('#prompt-preview').scrollIntoView({behavior:'smooth',block:'center'});toast('Your agent prompt is ready.');};$('#copy-prompt').onclick=async()=>{try{await navigator.clipboard.writeText(prompt());toast('Prompt copied.');}catch{toast('Clipboard unavailable. Download PROJECT.md instead.');}};document.querySelectorAll('[data-export]').forEach(e=>e.onclick=()=>{const name=e.dataset.export;let text=prompt();if(name==='AGENTS.md')text=`# ${state.brief.name||'Project'}\n\nRead PROJECT.md and TASKS.md before working.\n\n## Rules\n- Stay within the first milestone.\n- Preserve existing conventions.\n- Do not commit secrets.\n- Run the relevant checks after changes.\n- Report checks performed and remaining limitations.\n\n## Stack\n${state.brief.stack||'See PROJECT.md'}\n\n## Constraints\n${state.brief.constraints||'See PROJECT.md'}\n`;if(name==='TASKS.md')text='# Tasks\n\n'+(state.brief.features||'Define the first milestone').split('\n').filter(Boolean).map(s=>'- [ ] '+s.replace(/^[-*]\s*/, '')).join('\n')+'\n\n## Acceptance criteria\n'+(state.brief.verify||'Define success criteria')+'\n';download(name,text);});$('#backup').onclick=()=>download('vibe-workspace-backup.json',JSON.stringify({version:1,...state},null,2),'application/json');$('#import-backup').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>1000000)throw Error('File is too large.');const imported=JSON.parse(await file.text());if(imported.version!==1||!imported.brief||!Array.isArray(imported.saved)||typeof imported.checks!=='object')throw Error('Not a valid workbench backup.');state={brief:Object.fromEntries(fields.map(([k])=>[k,String(imported.brief[k]||'').slice(0,12000)])),saved:imported.saved.filter(id=>data.docs.some(d=>d.id===id)),checks:imported.checks||{},theme:imported.theme==='dark'?'dark':'light',sessionNote:String(imported.sessionNote||'').slice(0,12000)};persist();applyTheme();project();$('#saved-count').textContent=state.saved.length;toast('Workspace restored from backup.');}catch(err){toast('Import failed: '+err.message);}};}
function session(){const p=progress();$('#main').innerHTML=shell('A better building rhythm.','A lightweight checklist adapted from the playbooks. Check items as you work.',`<button id="reset-session">Start fresh session</button>`)+`<div class="panel"><div class="session-head"><h2>${esc(state.brief.name||'Current session')}</h2><span class="subtle" data-progress-text></span></div><div class="progress" style="margin-bottom:25px"><div data-progress-bar></div></div>${checkRows()}</div><div class="section-title"><h2>Keep a handoff note</h2><button id="export-session">Export session.md</button></div><div class="panel"><label class="subtle" for="session-note">What changed, what passed, and what comes next?</label><textarea id="session-note" style="margin-top:10px" placeholder="Capture enough context to pick this up in your next session.">${esc(state.sessionNote||'')}</textarea></div><p class="note">Adapted checklist · <a class="text-link" href="#library/vibe">Vibe Coding Playbook</a> & <a class="text-link" href="#library/engineering">Microsoft Engineering Fundamentals</a></p>`;bindChecks();updateProgress();$('#session-note').oninput=e=>{state.sessionNote=e.target.value;persist();};$('#reset-session').onclick=()=>{state.checks={};state.sessionNote='';persist();session();toast('Fresh session started.');};$('#export-session').onclick=()=>download('SESSION.md',`# Session: ${state.brief.name||'Project'}\n\n${state.sessionNote||'No handoff notes yet.'}\n\n`+checklist.map((g,gi)=>`## ${g[0]}\n`+g[1].map((t,i)=>`- [${state.checks[`${gi}-${i}`]?'x':' '}] ${t}`).join('\n')).join('\n\n'));}
function sources(){const sources=[['Microsoft Engineering Fundamentals','https://microsoft.github.io/code-with-engineering-playbook/','CC BY 4.0','licenses/code-with-engineering-playbook.txt','All Markdown documentation is indexed. Original wording is retained; layout and Markdown presentation are simplified.'],['Vibe Coding Playbook · plamen5rov','https://github.com/plamen5rov/vibe-coding-playbook','MIT','licenses/vibe-coding-playbook.txt','All 13 guide chapters are indexed. Original wording is retained; illustration references are omitted.'],['Collaborative UX Glossary · UX Mastery','https://github.com/uxmastery/collaborative-ux-glossary','CC BY-SA 4.0','licenses/ux-glossary.txt','Definitions are reproduced with simplified formatting. The glossary content and adaptations remain under CC BY-SA 4.0.'],['UI/UX Front-End Resources · Michael P Wright','https://gist.github.com/sm3dev/be972ae57ff94d5086a2bb403e995530','No license declared',null,'Only resource link titles, categories, and destinations are indexed. Original collection is preserved in the local checkout. Affiliate markers are retained.']];$('#main').innerHTML=shell('Built on open knowledge.','Original authors, licenses, and the source snapshots behind this workbench.')+`<div class="panel">${sources.map((s,i)=>`<section class="source"><h3>${s[0]}</h3><p class="subtle">${s[4]}</p><p><a target="_blank" rel="noopener noreferrer" href="${s[1]}">Original source ↗</a> · ${s[3]?`<a href="${s[3]}" target="_blank">${s[2]}</a>`:s[2]}</p><code>Snapshot: ${esc(data.provenance[i]?.commit||'See local source')}</code></section>`).join('')}</div><p class="note">This independent workbench is not affiliated with the source authors. Content is a downloaded snapshot, not a live feed. Project briefs, session notes, and bookmarks are stored in this browser; use Export workspace backup to move them.</p>`;}
function route(){search='';filter='';letter='';let [page,sub]=(location.hash.slice(1)||'overview').split('/');document.querySelectorAll('[data-nav]').forEach(e=>e.classList.toggle('active',e.dataset.nav===(page==='library'?sub:page)));document.querySelectorAll('header nav a').forEach(e=>e.classList.toggle('active',e.hash===(['overview','project','session','bookmarks'].includes(page)?'#overview':page==='library'?'#library':page==='resources'?'#resources':'')));$('#saved-count').textContent=state.saved.length;if(page==='account')platformAccount();else if(page==='build')builder();else if(page==='library')library(sub);else if(page==='bookmarks')library('',true);else if(page==='project')project();else if(page==='session')session();else if(page==='glossary')glossary();else if(page==='resources')resources();else if(page==='sources')sources();else overview();window.scrollTo(0,0);}
fetch('content.json').then(r=>{if(!r.ok)throw Error('Content unavailable');return r.json();}).then(d=>{data=d;route();window.addEventListener('hashchange',route);}).catch(()=>{$('#main').innerHTML='<div class="empty"><h1>Could not load the library.</h1><p>Open this app through the local server, or reload the hosted site.</p><button onclick="location.reload()">Try again</button></div>';});

